<template><section><div class="page-head"><div><span class="eyebrow">Listen your way</span><h1 class="page-title">Music</h1><p class="muted">Search Spotify, YouTube Music or TuneIn and open results with the service.</p></div></div><div class="card"><div class="row"><select class="select" v-model="state.musicService"><option>Spotify</option><option>YouTube Music</option><option>Tune-In</option></select><form class="row" @submit.prevent="$emit('action',{action:'music-search',payload:$event.target.query.value})"><input class="input" name="query" placeholder="Artist, track or playlist" required><button class="button">Search ↗</button></form></div><p class="muted">Search opens the selected provider in a new tab. Spotify and YouTube Music embed playback require provider authentication and are not proxied by this app.</p></div><div v-if="state.showPlayer" class="card" style="margin-top:16px"><div class="row"><h2 class="grow">Search on {{state.musicService}}</h2><a class="button" :href="state.mediaUrl" target="_blank" rel="noopener">Open “{{state.musicQuery}}” ↗</a></div><iframe v-if="state.musicService==='Spotify'" class="video-frame" style="aspect-ratio:16/6" :src="'https://open.spotify.com/embed/search/'+encodeURIComponent(state.musicQuery)" title="Spotify search" loading="lazy" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture"></iframe><iframe v-else-if="state.musicService==='YouTube Music'" class="video-frame" :src="'https://www.youtube-nocookie.com/embed?listType=search&list='+encodeURIComponent(state.musicQuery)" title="YouTube Music search" loading="lazy" allow="autoplay; encrypted-media; picture-in-picture"></iframe></div><div class="section-head"><h2>Your device</h2><button class="button-secondary" @click="$emit('action',{action:'file-select'})">Add music files</button></div><div v-for="file in state.files.filter(f=>f.type.startsWith('audio/'))" :key="file.url" class="station"><div class="grow"><strong>{{file.name}}</strong><small>On this device</small></div><audio controls :src="file.url"></audio></div><div v-if="!state.files.some(f=>f.type.startsWith('audio/'))" class="empty">Your local audio files will appear here.</div></section></template>
